"""Copilot skills: packaged runbooks the Copilot loads on demand.

Skills live under ``rasa/builder/copilot/skills/<use_case>/<name>/SKILL.md``, with
optional ``references/*.md`` files next to the ``SKILL.md``. The authoring rules are
in that directory's ``README.md``. This module parses the skills into an immutable
:class:`SkillCatalog`. It does not depend on the agent framework, so any Copilot
agent can pick its skills from the catalog with a :class:`SkillPolicy`.
"""

from __future__ import annotations

import functools
import importlib.resources
from enum import Enum
from importlib.resources.abc import Traversable

import structlog
from pydantic import BaseModel, ConfigDict, Field
from pydantic import ValidationError as PydanticValidationError
from ruamel.yaml import YAMLError

from rasa.builder.copilot.constants import COPILOT_SKILLS_DIR
from rasa.builder.copilot.exceptions import InvalidCopilotSkillError
from rasa.shared.constants import PACKAGE_NAME
from rasa.shared.utils.yaml import read_yaml

structlogger = structlog.get_logger()

SKILL_FILE_NAME = "SKILL.md"
SKILL_REFERENCES_DIR_NAME = "references"
_FRONTMATTER_DELIMITER = "---"


class SkillUseCase(str, Enum):
    """What a skill is for; each value names a directory under ``copilot/skills/``."""

    MANTLE = "mantle"


class SkillSource(BaseModel):
    """The IDE skill a Copilot skill was adapted from.

    ``path`` is relative to ``rasa/cli/tools/skills_data/`` and ``version`` is the
    IDE skill's ``metadata.version`` that the Copilot skill currently matches.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    path: str = Field(min_length=1)
    version: str = Field(min_length=1)


class SkillFrontmatter(BaseModel):
    """The YAML frontmatter of a ``SKILL.md``; unknown keys are rejected."""

    model_config = ConfigDict(frozen=True, extra="forbid", str_strip_whitespace=True)

    name: str = Field(pattern=r"^[a-z0-9]+(-[a-z0-9]+)*$", max_length=64)
    description: str = Field(min_length=1, max_length=1024)
    version: str = Field(pattern=r"^\d+\.\d+\.\d+$")
    tools: tuple[str, ...] = ()
    source: SkillSource | None = None


class CopilotSkill(BaseModel):
    """A validated Copilot skill: its frontmatter, body, and reference files.

    ``references`` maps each reference file's path relative to the skill
    directory (``references/<file>.md``) to its content.
    """

    model_config = ConfigDict(frozen=True)

    use_case: SkillUseCase
    frontmatter: SkillFrontmatter
    body: str
    references: dict[str, str] = Field(default_factory=dict)

    @property
    def name(self) -> str:
        """The skill's name, which is also its directory name."""
        return self.frontmatter.name

    @property
    def description(self) -> str:
        """When to use the skill; the model routes on this text."""
        return self.frontmatter.description

    @property
    def version(self) -> str:
        """The skill's semantic version."""
        return self.frontmatter.version


class SkillPolicy(BaseModel):
    """The skill use cases an agent is given.

    Values are validated against :class:`SkillUseCase`, so a policy can only name
    use cases that exist.
    """

    model_config = ConfigDict(frozen=True)

    use_cases: frozenset[SkillUseCase]


class SkillCatalog(BaseModel):
    """The valid Copilot skills, ordered by use case and then by name."""

    model_config = ConfigDict(frozen=True)

    skills: tuple[CopilotSkill, ...] = ()

    @classmethod
    def load(cls, root: Traversable) -> SkillCatalog:
        """Parse every skill under *root*, logging and skipping invalid ones.

        An invalid skill never fails the caller. The catalog is read while serving
        a Copilot turn, and one broken skill must not take the turn down with it;
        tests over the packaged skills keep them valid.

        Args:
            root: Directory with one subdirectory per :class:`SkillUseCase`.

        Returns:
            A catalog of every valid skill under *root*.
        """
        skills = [
            skill
            for use_case, use_case_dir in _use_case_directories(root)
            for skill_dir in _subdirectories(use_case_dir)
            if (skill := _load_skill(use_case, skill_dir)) is not None
        ]
        return cls(skills=tuple(skills))

    def for_use_case(self, use_case: SkillUseCase) -> tuple[CopilotSkill, ...]:
        """Return the skills of *use_case*."""
        return tuple(skill for skill in self.skills if skill.use_case == use_case)

    def for_policy(self, policy: SkillPolicy) -> tuple[CopilotSkill, ...]:
        """Return the skills of every use case *policy* includes."""
        return tuple(
            skill for skill in self.skills if skill.use_case in policy.use_cases
        )

    def get(self, name: str) -> CopilotSkill | None:
        """Return the skill called *name*, or ``None`` if there is none."""
        return next((skill for skill in self.skills if skill.name == name), None)


@functools.cache
def get_skill_catalog() -> SkillCatalog:
    """Return the catalog of skills packaged with Rasa, loaded once per process."""
    return SkillCatalog.load(
        importlib.resources.files(f"{PACKAGE_NAME}.{COPILOT_SKILLS_DIR}")
    )


def _use_case_directories(
    root: Traversable,
) -> list[tuple[SkillUseCase, Traversable]]:
    """Pair each directory under *root* with the use case it names.

    A directory that names no :class:`SkillUseCase` is logged and skipped.
    """
    pairs: list[tuple[SkillUseCase, Traversable]] = []
    for directory in _subdirectories(root):
        try:
            pairs.append((SkillUseCase(directory.name), directory))
        except ValueError:
            structlogger.warning(
                "copilot_v2.skills.unknown_use_case", directory=directory.name
            )
    return pairs


def _subdirectories(directory: Traversable) -> list[Traversable]:
    """Return the subdirectories of *directory*, sorted by name.

    Names starting with ``_`` or ``.`` are skipped, which covers ``__pycache__``
    next to the package's ``__init__.py``.
    """
    return sorted(
        (
            entry
            for entry in directory.iterdir()
            if entry.is_dir() and not entry.name.startswith(("_", "."))
        ),
        key=lambda entry: entry.name,
    )


def _load_skill(use_case: SkillUseCase, skill_dir: Traversable) -> CopilotSkill | None:
    """Parse one skill directory, or log why it is invalid and return ``None``."""
    try:
        return _parse_skill(use_case, skill_dir)
    except (
        InvalidCopilotSkillError,
        PydanticValidationError,
        YAMLError,
        OSError,
        UnicodeDecodeError,
    ) as exc:
        structlogger.warning(
            "copilot_v2.skills.invalid_skill",
            use_case=use_case.value,
            skill_directory=skill_dir.name,
            error_type=type(exc).__name__,
            error_message=str(exc),
        )
        return None


def _parse_skill(use_case: SkillUseCase, skill_dir: Traversable) -> CopilotSkill:
    """Parse and validate the skill in *skill_dir*.

    Raises:
        InvalidCopilotSkillError: If ``SKILL.md`` is missing, has no frontmatter,
            or names a skill other than its directory.
        PydanticValidationError: If the frontmatter does not match
            :class:`SkillFrontmatter`.
        YAMLError: If the frontmatter is not valid YAML.
    """
    skill_file = skill_dir / SKILL_FILE_NAME
    if not skill_file.is_file():
        raise InvalidCopilotSkillError(f"'{skill_dir.name}' has no {SKILL_FILE_NAME}.")
    frontmatter_text, body = _split_frontmatter(skill_file.read_text(encoding="utf-8"))
    # Frontmatter text reaches the model, so ${VAR} must stay literal: expanding
    # it could leak environment secrets into prompts.
    frontmatter = SkillFrontmatter.model_validate(
        read_yaml(frontmatter_text, expand_env_vars=False)
    )
    if frontmatter.name != skill_dir.name:
        raise InvalidCopilotSkillError(
            f"Skill name '{frontmatter.name}' does not match its directory "
            f"'{skill_dir.name}'."
        )
    return CopilotSkill(
        use_case=use_case,
        frontmatter=frontmatter,
        body=body.strip(),
        references=_read_references(skill_dir),
    )


def _split_frontmatter(content: str) -> tuple[str, str]:
    """Split ``SKILL.md`` text into its YAML frontmatter and its markdown body.

    Raises:
        InvalidCopilotSkillError: If the text does not open with a ``---`` block.
    """
    lines = content.splitlines()
    closing_index = None
    if lines and lines[0].strip() == _FRONTMATTER_DELIMITER:
        closing_index = next(
            (
                index
                for index in range(1, len(lines))
                if lines[index].strip() == _FRONTMATTER_DELIMITER
            ),
            None,
        )
    if closing_index is None:
        raise InvalidCopilotSkillError(
            f"{SKILL_FILE_NAME} must open with YAML frontmatter (--- ... ---)."
        )
    return "\n".join(lines[1:closing_index]), "\n".join(lines[closing_index + 1 :])


def _read_references(skill_dir: Traversable) -> dict[str, str]:
    """Read the skill's ``references/*.md`` files, keyed by relative path."""
    references_dir = skill_dir / SKILL_REFERENCES_DIR_NAME
    if not references_dir.is_dir():
        return {}
    return {
        f"{SKILL_REFERENCES_DIR_NAME}/{entry.name}": entry.read_text(encoding="utf-8")
        for entry in sorted(references_dir.iterdir(), key=lambda entry: entry.name)
        if entry.is_file() and entry.name.endswith(".md")
    }
